/**
 * Upload geometry: the exact pixel and quality arithmetic the web uploader
 * performs, as pure functions.
 *
 * Pure (no imports outside lib/r2-upload, no browser globals) so it runs under
 * `node --test` and so the Vyavasth Studio app can reproduce it. Its golden
 * vectors are generated by running THESE functions, so the expression order in
 * each one is load-bearing: `(h / w) * max` and `h * max / w` round differently
 * in doubles, and Kotlin and Swift must do exactly what JavaScript does here.
 */

import { UPLOAD_SPEC } from "./spec.ts";

export type Dims = { width: number; height: number };

/**
 * browser-image-compression 2.0.2, `handleMaxWidthOrHeight` in lib/utils.js:
 *
 *   needToHandle = isFinite(max) && (width > max || height > max)
 *   if (width > height) { newCanvas.width = max; newCanvas.height = (height / width) * max }
 *   else                { newCanvas.width = (width / height) * max; newCanvas.height = max }
 *
 * Never upscales: a source at or under `max` on both edges keeps its size. The
 * division happens first, then the multiplication, in doubles; the canvas
 * `width`/`height` setters (WebIDL `unsigned long`) truncate toward zero, which
 * is `Math.trunc` here. A square takes the `else` branch and becomes max x max.
 */
function libraryResizeDims(w: number, h: number, max: number): Dims {
  const needToHandle = Number.isFinite(max) && (w > max || h > max);
  if (!needToHandle) return { width: w, height: h };
  if (w > h) {
    return { width: max, height: Math.trunc((h / w) * max) };
  }
  return { width: Math.trunc((w / h) * max), height: max };
}

/**
 * `Math.max(1, Math.round(dim * scale))` with `scale = min(1, max / longEdge)`:
 * the rule `downscaleToView` and `drawThumbnail` in compressor.ts use when they
 * draw an already-decoded bitmap onto a smaller canvas. Never upscales.
 */
function roundedFitDims(w: number, h: number, max: number): Dims {
  const scale = Math.min(1, max / Math.max(w, h));
  return {
    width: Math.max(1, Math.round(w * scale)),
    height: Math.max(1, Math.round(h * scale)),
  };
}

/** The delivery view's dimensions for a source of `w` x `h` (oriented). */
export function viewDims(w: number, h: number): Dims {
  return libraryResizeDims(w, h, UPLOAD_SPEC.image.viewMaxDim);
}

/** The 4K archive's dimensions for a source of `w` x `h` (oriented). */
export function archiveDims(w: number, h: number): Dims {
  return libraryResizeDims(w, h, UPLOAD_SPEC.image.archiveMaxDim);
}

/** The delivery view drawn from a decoded 4K archive of `w` x `h`
 *  (compressor.ts `downscaleToView`). */
export function viewFromArchiveDims(w: number, h: number): Dims {
  return roundedFitDims(w, h, UPLOAD_SPEC.image.viewMaxDim);
}

/** The 480px grid thumbnail drawn from a decoded view of `w` x `h`
 *  (compressor.ts `drawThumbnail`). */
export function thumbDims(w: number, h: number): Dims {
  return roundedFitDims(w, h, UPLOAD_SPEC.image.thumbMaxDim);
}

/**
 * The JPEG qualities browser-image-compression 2.0.2 tries for one image
 * (`compress` in lib/image-compression.js), in order.
 *
 * Index 0 is `initial`, the first encode. When that JPEG is larger than the
 * source FILE (`tempFile.size > file.size`), the library re-encodes the same
 * pixels (dimensions unchanged, because `maxSizeMB` is unset) with
 * `quality *= 0.95`, up to `maxIteration` (10) more times, and stops at the
 * first result that is no larger than the source. If all ten are still larger
 * it returns the LAST one (index 10), not the smallest and not the first.
 *
 * Computed by repeated multiplication, exactly as the library does, so every
 * engine encodes with bit-identical floats (0.8, 0.76, 0.722, 0.6859, …).
 */
export function sizeGuardQualities(initial: number): number[] {
  const out = [initial];
  let quality = initial;
  for (let i = 0; i < UPLOAD_SPEC.image.sizeGuardMaxIterations; i++) {
    quality *= UPLOAD_SPEC.image.sizeGuardQualityFactor;
    out.push(quality);
  }
  return out;
}

/** The nine anchors a watermark preset can use (`WatermarkPosition` in
 *  lib/types.ts, restated so this module imports nothing outside r2-upload). */
export type WatermarkAnchor =
  | "top-left"
  | "top-center"
  | "top-right"
  | "middle-left"
  | "center"
  | "middle-right"
  | "bottom-left"
  | "bottom-center"
  | "bottom-right";

/**
 * The watermark's drawn size on a photo `W` wide: `size`% of the photo's width,
 * height keeping the mark's own aspect. Not rounded: the canvas draws at
 * fractional sizes, so the engines must too.
 */
export function watermarkSize(
  W: number,
  sizePercent: number,
  markW: number,
  markH: number,
): { width: number; height: number } {
  const width = (sizePercent / 100) * W;
  const height = width * (markH / markW);
  return { width, height };
}

/**
 * Top-left corner of a `wmW` x `wmH` watermark on a `W` x `H` photo (mirrors
 * `watermarkBoxStyle` in WatermarkEditorModal).
 *
 * The inset is `watermarkEdgeMarginRatio` of the shorter edge, applied as the
 * same pixel amount on both axes for an even gap in every corner. Not rounded.
 */
export function watermarkPlacement(
  position: WatermarkAnchor,
  W: number,
  H: number,
  wmW: number,
  wmH: number,
): { x: number; y: number } {
  const [v, h] = position === "center" ? ["middle", "center"] : position.split("-");
  // Uniform pixel inset on both axes for an even gap in every corner.
  const m = UPLOAD_SPEC.image.watermarkEdgeMarginRatio * Math.min(W, H);

  let x: number;
  if (h === "left") x = m;
  else if (h === "right") x = W - wmW - m;
  else x = (W - wmW) / 2;

  let y: number;
  if (v === "top") y = m;
  else if (v === "bottom") y = H - wmH - m;
  else y = (H - wmH) / 2;

  // A mark sized to (or near) the full frame has no room for the inset. Keep it
  // in frame rather than letting the margin push part of it off the canvas —
  // the gap is a nicety, staying inside the photo is not.
  return {
    x: clamp(x, 0, Math.max(0, W - wmW)),
    y: clamp(y, 0, Math.max(0, H - wmH)),
  };
}

/** Watermark opacity percentage as canvas `globalAlpha`: 0..1, NaN -> 1. */
export function watermarkAlpha(opacityPercent: number): number {
  const n = opacityPercent / 100;
  if (Number.isNaN(n)) return 1;
  return Math.min(1, Math.max(0, n));
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}
